SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, COUNT(DISTINCT salary) AS unique_levels FROM employees WHERE level IS NULL GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_FORMAT(hire_date, 'yyyy-MM') ORDER BY hire_month DESC, unique_levels DESC
